+static void openUrlWithService(KService::Ptr service, const QUrl &url, const QString &mimeType = QString())
+{
+    // prevents using a service that does not support opening a mime type for a file it created, e.g. a screenshot tool
+    if (!mimeType.isEmpty() && !service->hasMimeType(mimeType)) {
+        service = KApplicationTrader::preferredService(mimeType);
+        if (!service) {
+            return;
+        }
+    }
+
+    auto *job = new KIO::ApplicationLauncherJob(service);
+    job->setUrls({url});
+    job->setUiDelegate(new KNotificationJobUiDelegate(KJobUiDelegate::AutoErrorHandlingEnabled));
+    job->start();
+}
