+void IconApplet::populateDynamicActions()
+{
+    qDeleteAll(std::exchange(m_dynamicActions, {}));
+
+    if (!m_localPath.isEmpty()) {
+        KDesktopFile desktopFile(m_localPath);
+
+        if (desktopFile.hasApplicationType()) {
+            // m_localPath is our own copy, apps report their usage under the name of the original desktop file
+            QString desktopEntryName = m_url.fileName();
+            if (desktopEntryName.endsWith(QLatin1String(".desktop"))) {
+                desktopEntryName.chop(8);
+            }
+
+            // Since we can't have dynamic jump list actions, at least add the user's "Places" for file managers.
+            if (desktopFile.desktopGroup().readXdgListEntry(QStringLiteral("Categories")).contains(QLatin1String("FileManager"))) {
+                m_dynamicActions = placesActions();
+            } else {
+                m_dynamicActions = recentDocumentActions(desktopEntryName);
+            }
+        }
+    }
+
+    Q_EMIT extraActionsChanged();
+}
