+QList<QAction *> IconApplet::placesActions()
+{
+    QList<QAction *> actions;
+
+    QString previousGroup;
+    QMenu *subMenu = nullptr;
+
+    KFilePlacesModel placesModel;
+    for (int i = 0; i < placesModel.rowCount(); ++i) {
+        const QModelIndex idx = placesModel.index(i, 0);
+
+        if (placesModel.isHidden(idx)) {
+            continue;
+        }
+
+        const QString groupName = idx.data(KFilePlacesModel::GroupRole).toString();
+        if (previousGroup.isEmpty()) { // Skip first group heading.
+            previousGroup = groupName;
+        }
+
+        // Put all subsequent categories into a submenu.
+        if (previousGroup != groupName) {
+            auto *subMenuAction = new QAction(groupName, this);
+            subMenu = new QMenu();
+            subMenu->setAttribute(Qt::WA_TranslucentBackground);
+            // Cannot parent a QMenu to a QAction, need to delete it manually.
+            connect(subMenuAction, &QObject::destroyed, subMenu, &QObject::deleteLater);
+            subMenuAction->setMenu(subMenu);
+
+            actions << subMenuAction;
+
+            previousGroup = groupName;
+        }
+
+        const QUrl url = idx.data(KFilePlacesModel::UrlRole).toUrl();
+
+        auto *placeAction = new QAction(idx.data(Qt::DecorationRole).value<QIcon>(), idx.data(Qt::DisplayRole).toString(), this);
+        connect(placeAction, &QAction::triggered, this, [localPath = m_localPath, url] {
+            openUrlWithService(KService::Ptr(new KService(localPath)), url);
+        });
+
+        if (subMenu) {
+            placeAction->setParent(subMenu);
+            subMenu->addAction(placeAction);
+        } else {
+            actions << placeAction;
+        }
+    }
+
+    if (!actions.isEmpty()) {
+        auto *sectionAction = new QAction(i18nc("@title:group for section of menu items", "Places"), this);
+        sectionAction->setSeparator(true);
+        actions.prepend(sectionAction);
+    }
+
+    return actions;
+}
+
+QList<QAction *> IconApplet::recentDocumentActions(const QString &desktopEntryName)
+{
+    QList<QAction *> actions;
+
+    // clang-format off
+    auto query = UsedResources
+        | RecentlyUsedFirst
+        | Agent(desktopEntryName)
+        | Type::any()
+        | Activity::current()
+        | Url::file();
+    // clang-format on
+
+    ResultSet results(query);
+
+    for (auto resultIt = results.begin(); resultIt != results.end() && actions.count() < 5; ++resultIt) {
+        const QString mimeType = (*resultIt).mimetype();
+        const QUrl url = (*resultIt).url();
+
+        if (!url.isValid()) {
+            continue;
+        }
+
+        const KFileItem fileItem(url, mimeType);
+
+        if (!fileItem.isFile()) {
+            continue;
+        }
+
+        auto *action = new QAction(QIcon::fromTheme(fileItem.iconName()), url.fileName(), this);
+        connect(action, &QAction::triggered, this, [localPath = m_localPath, url, mimeType] {
+            openUrlWithService(KService::Ptr(new KService(localPath)), url, mimeType);
+        });
+
+        actions << action;
+    }
+
+    if (actions.isEmpty()) {
+        return actions;
+    }
+
+    auto *sectionAction = new QAction(i18nc("@title:group for section of menu items", "Recent Files"), this);
+    sectionAction->setSeparator(true);
+    actions.prepend(sectionAction);
+
+    auto *forgetAction = new QAction(QIcon::fromTheme(QStringLiteral("edit-clear-history")), i18nc("@action:inmenu", "Forget Recent Files"), this);
+    connect(forgetAction, &QAction::triggered, this, [desktopEntryName] {
+        KRecentDocument::removeApplication(desktopEntryName);
+
+        // clang-format off
+        auto query = UsedResources
+            | Agent(desktopEntryName)
+            | Type::any()
+            | Activity::current()
+            | Url::file();
+        // clang-format on
+
+        KAStats::forgetResources(query);
+    });
+    actions << forgetAction;
+
+    return actions;
+}
